package com.typenull.pingdom.place.application.service.review;
import com.typenull.pingdom.place.api.dto.review.*; import com.typenull.pingdom.place.domain.review.PlaceReview; import com.typenull.pingdom.place.infrastructure.persistence.place.*; import com.typenull.pingdom.shared.exception.*; import java.time.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class PlaceReviewService { private final MapPlaceRepository placeRepository; private final PlaceReviewRepository reviewRepository; private final Clock clock;
 @Transactional public PlaceReviewResponse create(Long userId, Long placeId, PlaceReviewCreateRequest request){var place=placeRepository.findById(placeId).orElseThrow(()->new MapException(MapErrorCode.PLACE_NOT_FOUND)); return PlaceReviewResponse.from(reviewRepository.save(PlaceReview.create(place,userId,request.recommendReason(),request.content(),request.imageUrls()==null?java.util.List.of():request.imageUrls(),LocalDateTime.now(clock))));}
 @Transactional(readOnly=true) public Page<PlaceReviewResponse> list(Long placeId,int page,int limit){if(!placeRepository.existsById(placeId))throw new MapException(MapErrorCode.PLACE_NOT_FOUND); return reviewRepository.findAllByPlace_Id(placeId,PageRequest.of(Math.max(0,page-1),Math.min(100,Math.max(1,limit)),Sort.by("createdAt").descending())).map(PlaceReviewResponse::from);}}
